																	"*": {
																		"LabelSlider__": {
																			"type": "Label",
																			"data": false,
																			"stamp": 83,
																			"options": {
																				"label": "_Days",
																				"version": 0
																			}
																		},
																		"Slider__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 82,
																			"options": {
																				"label": "_Days",
																				"activable": true,
																				"htmlContent": "<div>\n\t<input type=\"range\" id=\"slider\" class=\"custom-slider\" min=\"1\" value=\"1\" step=\"1\" />\n\t<input type=\"number\" id=\"numberSlider\" class=\"number-input\" value=\"1\" readonly />\n\t<input type=\"hidden\" id=\"onActionLoad\" onclick=\"onActionLoad(event)\" />\n</div>\n\n<script  type=\"text/javascript\">\n\tInit();\n\n\tfunction onActionLoad(event)\n\t{\n\t\tvar slider =  document.querySelector('#slider');\n\t\tvar number =  document.querySelector('#numberSlider');\n\t\tif (event)\n\t\t{\n\t\t\tif (event.maxDays)\n\t\t\t{\n\t\t\t\tslider.max = event.maxDays;\n\t\t\t}\n\t\t\telse if (event.value)\n\t\t\t{\n\t\t\t\tslider.value = event.value;\n\t\t\t\tnumber.value = event.value;\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction postMsg(event)\n\t{\n\t\tvar originControl = \"Slider__\";\n\t\tvar number =  document.querySelector('#numberSlider');\n\t\tnumber.value = this.value;\n\n\t\twindow.postMessage(\n\t\t{\n\t\t\teventName: \"input\",\n\t\t\tcontrol: originControl,\n\t\t\tvalue: this.value\n\t\t}, document.location.origin);\n\t};\n\n\tfunction Init()\n\t{\n\t\tvar slider = document.querySelector('#slider');\n\t\tslider.addEventListener(\"input\", postMsg);\n\t}\n</script>",
																				"css": "#numberSlider {\n\twidth: 30px;\n    cursor: auto;\n\tcaret-color: transparent;\n}\n\n.custom-slider{\n\taccent-color: #008998;\n}\n\ninput[type=range].custom-slider {\n\twidth: 130px;\n}\n\n/* Internet Explorer */\ninput[type=range]::-ms-track {\n\twidth: 130px;\n\theight: 8px;\n\n\t/*remove bg colour from the track, we'll use ms-fill-lower and ms-fill-upper instead */\n\tbackground: transparent;\n\n\t/*leave room for the larger thumb to overflow with a transparent border */\n\tborder-color: transparent;\n\tborder-width: 6px 0;\n\n\t/*remove default tick marks*/\n\tcolor: transparent;\n}\n\ninput[type=range]::-ms-fill-lower {\n\tbackground: #008998;\n\tborder-radius: 10px;\n}\n\ninput[type=range]::-ms-fill-upper {\n\tbackground: #ddd;\n\tborder-radius: 10px;\n}\n\ninput[type=range]::-ms-thumb {\n\tborder: none;\n\theight: 16px;\n\twidth: 16px;\n\tborder-radius: 50%;\n\tbackground: #008998;\n}\n\ninput[type=range]:focus::-ms-fill-lower {\n\tbackground: #008998;\n}\n\ninput[type=range]:focus::-ms-fill-upper {\n\tbackground: #ccc;\n}\n",
